using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public sealed class DofusCharacter {public string id="",name="",server="",classCode="",alignment="",order="",guide="rsa-rush-sylvestre-accelere";}
public sealed class DofusProgress {public string characterId="",guide="",cursor="",notes="";public List<string> done=new List<string>();}
public sealed class DofusData {public string active="";public List<DofusCharacter> characters=new List<DofusCharacter>();public List<DofusProgress> progress=new List<DofusProgress>();public double width=370,height=570;public bool topmost=true,positionSaved;public double left,top;}
internal sealed class TougliGuideInfo {internal string Slug,Title,Category;internal int Level;}
internal sealed class TougliResource {internal string Name,Id;internal long Count;}
internal sealed class TougliStep {public string Display{get{return Section+" · "+Title;}}internal string Key,Title,Section,Details,Url,Coordinates,QuestId;internal bool CanComplete=true;internal List<TougliResource> Resources=new List<TougliResource>();}
internal sealed class TougliDocument {internal string Slug,Title,Description,Hash;internal List<TougliStep> Steps=new List<TougliStep>();}
internal static class DofusCompanion {
 internal static readonly string[] Classes={"","Feca","Osa","Enu","Sram","Xel","Eca","Eni","Iop","Cra","Sadi","Sacri","Panda","Roub","Zobal","Steamer","Elio","Hupper","Ougi","Forge"};
 internal static readonly string[] ClassNames={"Non renseignée","Féca","Osamodas","Enutrof","Sram","Xélor","Ecaflip","Eniripsa","Iop","Crâ","Sadida","Sacrieur","Pandawa","Roublard","Zobal","Steamer","Eliotrope","Huppermage","Ouginak","Forgelance"};
 internal static void Validate(Data d){if(d.dofus==null)d.dofus=new DofusData();var c=d.dofus;if(c.characters==null)c.characters=new List<DofusCharacter>();if(c.progress==null)c.progress=new List<DofusProgress>();if(c.characters.Count>30||c.progress.Count>1000||c.characters.Any(p=>p==null||String.IsNullOrWhiteSpace(p.id)||p.id.Length>100||String.IsNullOrWhiteSpace(p.name)||p.name.Length>60||(p.server??"").Length>60||!Classes.Contains(p.classCode)||!new[]{"","Bonta","Brak","Neutre"}.Contains(p.alignment)||!new[]{"","CV","OA","ES","CS","OP","EM"}.Contains(p.order)||!TougliReader.ValidSlug(p.guide))||c.characters.Select(p=>p.id).Distinct().Count()!=c.characters.Count)throw new InvalidDataException("Personnages Dofus invalides.");if(!c.characters.Any(p=>p.id==c.active))c.active=c.characters.Select(p=>p.id).FirstOrDefault()??"";
  if(c.progress.Any(p=>p==null||String.IsNullOrWhiteSpace(p.characterId)||p.characterId.Length>100||!TougliReader.ValidSlug(p.guide)||(p.cursor??"").Length>200||(p.notes??"").Length>10000||p.done==null||p.done.Count>10000||p.done.Any(k=>String.IsNullOrWhiteSpace(k)||k.Length>200)||p.done.Distinct().Count()!=p.done.Count)||c.progress.Select(p=>p.characterId+"/"+p.guide).Distinct().Count()!=c.progress.Count||c.progress.Sum(p=>p.done.Count)>50000)throw new InvalidDataException("Progression Dofus invalide.");if(Double.IsNaN(c.width)||Double.IsInfinity(c.width)||c.width<300||c.width>1400)c.width=370;if(Double.IsNaN(c.height)||Double.IsInfinity(c.height)||c.height<300||c.height>1400)c.height=570;if(Double.IsNaN(c.left)||Double.IsInfinity(c.left)||Double.IsNaN(c.top)||Double.IsInfinity(c.top)||Math.Abs(c.left)>100000||Math.Abs(c.top)>100000)c.positionSaved=false;
 }
 internal static DofusCharacter Character(Data d){return d.dofus.characters.FirstOrDefault(c=>c.id==d.dofus.active);}
 internal static DofusProgress Find(Data d,DofusCharacter c){return c==null?null:d.dofus.progress.FirstOrDefault(p=>p.characterId==c.id&&p.guide==c.guide);}
 internal static DofusProgress Get(Data d,DofusCharacter c){var p=Find(d,c);if(p==null){p=new DofusProgress{characterId=c.id,guide=c.guide};d.dofus.progress.Add(p);}return p;}
 internal static TougliStep Current(Data d,TougliDocument doc){var c=Character(d);if(c==null||doc==null||doc.Slug!=c.guide)return null;var p=Find(d,c);return (p==null?null:doc.Steps.FirstOrDefault(s=>s.Key==p.cursor))??doc.Steps.FirstOrDefault(s=>p==null||!p.done.Contains(s.Key))??doc.Steps.LastOrDefault();}
 internal static void Navigate(Store store,TougliDocument doc,int direction,bool complete){var c=Character(store.Value);var current=Current(store.Value,doc);if(c==null||current==null)return;if(complete&&!current.CanComplete)throw new InvalidOperationException("Configurez le choix de personnage ou consultez cette étape sur Tougli.");PersonalWorkflows.Change(store,()=>{var p=Get(store.Value,c);if(complete&&!p.done.Contains(current.Key))p.done.Add(current.Key);int index=doc.Steps.IndexOf(current);p.cursor=doc.Steps[Math.Max(0,Math.Min(doc.Steps.Count-1,index+direction))].Key;});}
 internal static void Toggle(Store store,TougliDocument doc){var c=Character(store.Value);var step=Current(store.Value,doc);if(c==null||step==null)return;if(!step.CanComplete)throw new InvalidOperationException("Choix à configurer avant de valider cette étape.");PersonalWorkflows.Change(store,()=>{var p=Get(store.Value,c);if(p.done.Contains(step.Key))p.done.Remove(step.Key);else p.done.Add(step.Key);});}
 internal static List<TougliResource> Remaining(Data d,TougliDocument doc){var c=Character(d);var p=Find(d,c);return doc.Steps.Where(s=>s.QuestId!=null&&(p==null||!p.done.Contains(s.Key))).GroupBy(s=>s.QuestId).Select(g=>g.First()).SelectMany(s=>s.Resources).GroupBy(r=>r.Id).Select(g=>new TougliResource{Id=g.Key,Name=g.First().Name,Count=g.Sum(r=>r.Count)}).OrderBy(r=>r.Name).ToList();}
}
